--- Returns the ids of a node's children, in evaluation order.
--- @param n SrcNode
--- @return NodeId[] kids
function M.children(n)
    local kids = {}
    if n.tag == 'Block' then
        for _, kid in ipairs(n.statements) do
            kids[#kids + 1] = kid
        end
    elseif n.tag == 'ClvRegion' then
        for _, kid in ipairs(n.statements) do
            kids[#kids + 1] = kid
        end
    elseif n.tag == 'Local' then
        for _, kid in ipairs(n.values) do
            kids[#kids + 1] = kid
        end
        for _, kid in ipairs(n.names) do
            kids[#kids + 1] = kid
        end
    elseif n.tag == 'LocalFunction' then
        kids[#kids + 1] = n.binder
        kids[#kids + 1] = n.func
    elseif n.tag == 'Set' then
        for _, kid in ipairs(n.targets) do
            kids[#kids + 1] = kid
        end
        for _, kid in ipairs(n.values) do
            kids[#kids + 1] = kid
        end
    elseif n.tag == 'Call' then
        kids[#kids + 1] = n.func
        for _, kid in ipairs(n.args) do
            kids[#kids + 1] = kid
        end
    elseif n.tag == 'If' then
        for _, kid in ipairs(n.arms) do
            kids[#kids + 1] = kid
        end
        if n.else_block ~= nil then
            kids[#kids + 1] = n.else_block
        end
    elseif n.tag == 'IfArm' then
        kids[#kids + 1] = n.cond
        kids[#kids + 1] = n.body
    elseif n.tag == 'While' then
        kids[#kids + 1] = n.cond
        kids[#kids + 1] = n.body
    elseif n.tag == 'Repeat' then
        kids[#kids + 1] = n.body
        kids[#kids + 1] = n.cond
    elseif n.tag == 'Fornum' then
        kids[#kids + 1] = n.start
        kids[#kids + 1] = n.limit
        if n.step ~= nil then
            kids[#kids + 1] = n.step
        end
        kids[#kids + 1] = n.var
        kids[#kids + 1] = n.body
    elseif n.tag == 'Forin' then
        for _, kid in ipairs(n.iters) do
            kids[#kids + 1] = kid
        end
        for _, kid in ipairs(n.names) do
            kids[#kids + 1] = kid
        end
        kids[#kids + 1] = n.body
    elseif n.tag == 'Return' then
        for _, kid in ipairs(n.values) do
            kids[#kids + 1] = kid
        end
    elseif n.tag == 'Function' then
        for _, kid in ipairs(n.directives) do
            kids[#kids + 1] = kid
        end
        for _, kid in ipairs(n.params) do
            kids[#kids + 1] = kid
        end
        kids[#kids + 1] = n.body
    elseif n.tag == 'Table' then
        for _, kid in ipairs(n.fields) do
            kids[#kids + 1] = kid
        end
    elseif n.tag == 'TableField' then
        if n.key ~= nil then
            kids[#kids + 1] = n.key
        end
        kids[#kids + 1] = n.value
    elseif n.tag == 'Index' then
        kids[#kids + 1] = n.obj
        kids[#kids + 1] = n.key
    elseif n.tag == 'BinOp' then
        kids[#kids + 1] = n.lhs
        kids[#kids + 1] = n.rhs
    elseif n.tag == 'UnOp' then
        kids[#kids + 1] = n.arg
    elseif n.tag == 'Paren' then
        kids[#kids + 1] = n.expr
    elseif n.tag == 'ClvTypeApply' then
        kids[#kids + 1] = n.base
        for _, kid in ipairs(n.args) do
            kids[#kids + 1] = kid
        end
    elseif n.tag == 'ClvTypeArray' then
        kids[#kids + 1] = n.elem
    elseif n.tag == 'ClvTypeUnion' then
        for _, kid in ipairs(n.members) do
            kids[#kids + 1] = kid
        end
    elseif n.tag == 'ClvTypeOptional' then
        kids[#kids + 1] = n.inner
    elseif n.tag == 'ClvTypeFun' then
        for _, kid in ipairs(n.generics) do
            kids[#kids + 1] = kid
        end
        for _, kid in ipairs(n.params) do
            kids[#kids + 1] = kid
        end
        for _, kid in ipairs(n.returns) do
            kids[#kids + 1] = kid
        end
    elseif n.tag == 'ClvTypeParam' then
        if n.type ~= nil then
            kids[#kids + 1] = n.type
        end
    elseif n.tag == 'ClvTypeReturn' then
        kids[#kids + 1] = n.type
    elseif n.tag == 'ClvTypeTable' then
        for _, kid in ipairs(n.fields) do
            kids[#kids + 1] = kid
        end
    elseif n.tag == 'ClvTypeField' then
        if n.key ~= nil then
            kids[#kids + 1] = n.key
        end
        kids[#kids + 1] = n.type
    elseif n.tag == 'ClvTypeTuple' then
        for _, kid in ipairs(n.items) do
            kids[#kids + 1] = kid
        end
    elseif n.tag == 'ClvPre' then
        kids[#kids + 1] = n.cond
    elseif n.tag == 'ClvPost' then
        kids[#kids + 1] = n.cond
    elseif n.tag == 'ClvParam' then
        kids[#kids + 1] = n.type
    elseif n.tag == 'ClvReturn' then
        kids[#kids + 1] = n.type
    elseif n.tag == 'ClvDecrease' then
        for _, kid in ipairs(n.measures) do
            kids[#kids + 1] = kid
        end
    elseif n.tag == 'ClvInvariant' then
        kids[#kids + 1] = n.cond
    elseif n.tag == 'ClvModuleInvariant' then
        kids[#kids + 1] = n.cond
    elseif n.tag == 'ClvClosureInvariant' then
        kids[#kids + 1] = n.cond
    elseif n.tag == 'ClvType' then
        for _, kid in ipairs(n.types) do
            kids[#kids + 1] = kid
        end
    elseif n.tag == 'ClvClass' then
        for _, kid in ipairs(n.generics) do
            kids[#kids + 1] = kid
        end
        for _, kid in ipairs(n.parents) do
            kids[#kids + 1] = kid
        end
    elseif n.tag == 'ClvField' then
        if n.key ~= nil then
            kids[#kids + 1] = n.key
        end
        kids[#kids + 1] = n.type
    elseif n.tag == 'ClvAlias' then
        for _, kid in ipairs(n.generics) do
            kids[#kids + 1] = kid
        end
        kids[#kids + 1] = n.type
    elseif n.tag == 'ClvGeneric' then
        if n.bound ~= nil then
            kids[#kids + 1] = n.bound
        end
    elseif n.tag == 'ClvCast' then
        if n.type ~= nil then
            kids[#kids + 1] = n.type
        end
    elseif n.tag == 'ClvAs' then
        kids[#kids + 1] = n.type
    elseif n.tag == 'ClvVararg' then
        kids[#kids + 1] = n.type
    elseif n.tag == 'ClvOverload' then
        kids[#kids + 1] = n.type
    elseif n.tag == 'ClvOperator' then
        if n.operand ~= nil then
            kids[#kids + 1] = n.operand
        end
        kids[#kids + 1] = n.result
    end
    return kids
end

return M
